//! 🧪️ Actual snapshot registry custody lends its original payload through the registered admission facade.
use super::*;
use crate::child_view::{ChildContentEntry,editor::{read::ChildEditorRead,source::{ChildEditorCapability,ChildEditorFields,ChildEditorRequest,ChildEditorCurrent,ChildEditorSourceCursor,ChildEditorSourceStep}}};
use semio_framework_io_ports::{EmbeddedChildAdmitterV1,EmbeddedChildAdmission,EmbeddedChildVectorSourceV1,ChildAdmissionSource,VectorGraphAdvance};
use store::os_store::snapshot_read::ErasedSnapshotRead;
use std::sync::Arc;
struct Admitter;
impl EmbeddedChildAdmitterV1 for Admitter{fn birth_demand(&self)->RetirementDemand{Default::default()}fn begin(&self,_:RetainedCloneGrant)->Result<(EmbeddedChildAdmission,RetainedCloneProgress),ValueError>{unreachable!("Provider laws only borrow the registered producer identity")}}
struct Vector;
impl EmbeddedChildVectorSourceV1 for Vector{fn read_demand(&self)->RetirementDemand{Default::default()}fn read<'a>(&self,_:ChildAdmissionSource<'a>,_:RetainedCloneGrant)->Result<VectorGraphAdvance<'a>,ValueError>{unreachable!("Provider laws only borrow the registered producer identity")}}
static ADMITTER:Admitter=Admitter;static VECTOR:Vector=Vector;
static REGISTRATION:ChildEditorRegistration<String>=ChildEditorRegistration::new(ChildEditorCapability{artifact_kind:"s.fixture.child",standard:"1",subset:"*",editor_id:"s.fixture.child@1/*#editor",command_id:"edit"},&ADMITTER,&VECTOR);
static OTHER:ChildEditorRegistration<String>=ChildEditorRegistration::new(ChildEditorCapability{artifact_kind:"s.fixture.child",standard:"1",subset:"*",editor_id:"s.fixture.child@1/*#editor",command_id:"edit"},&ADMITTER,&VECTOR);
fn generous()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:128}}
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn qualified(current:&ChildEditorCurrent<'_>)->crate::child_view::editor::source::ChildEditorStamp{let request=ChildEditorRequest{identity:11,expected_reference_identity:44,fields:current.fields};let mut cursor=ChildEditorSourceCursor::new();let stamp=loop{if let ChildEditorSourceStep::Ready(stamp)=cursor.advance(&request,current,generous()).unwrap(){break stamp}};cursor.cancel();assert!(cursor.close_one(generous()));stamp}
#[test]
fn actual_member_read_custody_and_registered_pair_are_the_provider_authority(){let laws:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();assert_eq!(laws["cases"].as_array().unwrap().len(),8);let registry=store::os_store::snapshot_read::SnapshotReadRegistryHandle::new();let payload=Arc::new(String::from("Original qualified Grüße 🌍"));let pointer=Arc::as_ptr(&payload);let lease=registry.try_issue(Arc::clone(&payload)).unwrap_or_else(|_|panic!("actual member registry"));let entry=ChildContentEntry{owner:String::new(),slot:"backgroundDrawing".into(),child_id:"drawing-child".into(),artifact_id:"drawing-artifact".into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:REGISTRATION.identity.artifact_kind.into(),standard:"1".into(),subset:"*".into()},revision:[42;32],snapshot:ErasedSnapshotRead::new(Arc::clone(&payload),lease)};let parent_revision=[31;32];let read=ChildEditorRead{read:entry.snapshot.typed::<String>().unwrap(),entry:&entry,parent_identity:22,parent_artifact:"layout",parent_revision:&parent_revision};let current=read.current(&REGISTRATION.identity);let stamp=qualified(&current);let mut custody=ChildEditorSourceCustody::new();let d=ChildEditorAdmissionProvider::<String>::demand();for denied in [RetainedCloneGrant{maximum_items:0,..exact(d)},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..exact(d)},RetainedCloneGrant{maximum_depth:d.depth-1,..exact(d)}]{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ChildEditorAdmissionProvider::admit(&custody,&REGISTRATION,7,denied));assert!(result.is_err());assert_eq!(result.err().unwrap().retained_progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}assert!(ChildEditorAdmissionProvider::admit(&custody,&REGISTRATION,7,exact(d)).is_err());while !custody.ready(){read.admit_original_source(&REGISTRATION.identity,&stamp,&mut custody,generous()).unwrap();}
 {let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ChildEditorAdmissionProvider::admit(&custody,&REGISTRATION,7,exact(d)));let(provider,p)=result.unwrap();assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));let address=provider.address();let actual=provider.read(address).unwrap();assert_eq!(actual.source.get().downcast_ref::<String>().unwrap()as*const String,pointer);assert!(std::ptr::eq(actual.admitter,REGISTRATION.admission));assert!(std::ptr::eq(actual.vector,REGISTRATION.vector));let(foreign,_)=ChildAdmissionAddress::admit(8,&stamp,generous()).unwrap();assert!(provider.read(foreign).is_err());let changed=[99;32];for parent in [true,false]{let fields=if parent{ChildEditorFields{parent_revision:&changed,..current.fields}}else{ChildEditorFields{child_revision:&changed,..current.fields}};let foreign_stamp=qualified(&ChildEditorCurrent{fields,..current});let(foreign,_)=ChildAdmissionAddress::admit(7,&foreign_stamp,generous()).unwrap();assert!(provider.read(foreign).is_err());}}
 let error=ChildEditorAdmissionProvider::admit(&custody,&OTHER,7,exact(d)).err().unwrap();assert_eq!(error.retained_progress().copied_bytes,ChildEditorAdmissionProvider::<String>::HEADER);custody.begin_close();assert!(ChildEditorAdmissionProvider::admit(&custody,&REGISTRATION,7,exact(d)).is_err());let mut close=custody.into_retirement().unwrap_or_else(|_|panic!("actual custody original retirement"));for _ in 0..10000{if close.terminal_is_empty(){break}let d=close.selected_demand(16*1024*1024).unwrap();close.step(exact(d)).unwrap();}assert!(close.terminal_is_empty());drop(read);let root=entry.snapshot.into_typed::<String>(&registry).unwrap_or_else(|_|panic!("same original registry payload"));assert_eq!(Arc::as_ptr(&root),pointer);drop(root);assert!(registry.terminal_is_empty());drop(payload);let mut registry=Some(store::os_store::snapshot_read::SnapshotReadRegistryAliasRetirement::new(registry));while registry.is_some(){store::os_store::snapshot_read::snapshot_registry_alias_close_step(&mut registry,generous()).unwrap();}}
